1	import { readdir, readFile } from 'node:fs/promises'
2	import { join } from 'node:path'
3	
4	export type SkillEntry = {
5	  name: string
6	  /** What the skill is for and when to load it, from its frontmatter. */
7	  description: string
8	  /** Folder holding SKILL.md; relative paths inside the skill resolve here. */
9	  dir: string
10	}
11	
12	/**
13	 * Workspace-relative roots, both in Claude Code's layout so one skill serves
14	 * both engines. `.agent/skills` is ours and wins when a name is in both.
15	 */
16	export const SKILL_ROOTS = ['.claude/skills', '.agent/skills']
17	
18	/** Every `<root>/<folder>/SKILL.md` under the workspace, one entry per name, sorted. */
19	export async function indexSkills(cwd: string): Promise<SkillEntry[]> {
20	  const byName = new Map<string, SkillEntry>()
21	  for (const root of SKILL_ROOTS) {
22	    for (const skill of await indexRoot(join(cwd, root))) byName.set(skill.name, skill)
23	  }
24	  return [...byName.values()].sort((a, b) => a.name.localeCompare(b.name))
25	}
26	
27	async function indexRoot(root: string): Promise<SkillEntry[]> {
28	  let folders
29	  try {
30	    folders = await readdir(root, { withFileTypes: true })
31	  } catch (error) {
32	    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return []
33	    throw error
34	  }
35	  const skills: SkillEntry[] = []
36	  for (const folder of folders) {
37	    if (!folder.isDirectory()) continue
38	    const dir = join(root, folder.name)
39	    const text = await readOptional(join(dir, 'SKILL.md'))
40	    if (text === undefined) continue
41	    const { frontmatter } = splitFrontmatter(text)
42	    skills.push({ name: frontmatter['name'] ?? folder.name, description: frontmatter['description'] ?? '', dir })
43	  }
44	  return skills
45	}
46	
47	/** The instructions the model reads when it loads the skill: SKILL.md without its frontmatter. */
48	export async function readSkillBody(skill: SkillEntry): Promise<string> {
49	  return splitFrontmatter(await readFile(join(skill.dir, 'SKILL.md'), 'utf8')).body
50	}
51	
52	/**
53	 * Splits a `---` frontmatter block off a markdown file. Understands the YAML
54	 * subset a skill header uses: `key: value` and the `>` / `|` block scalars.
55	 */
56	export function splitFrontmatter(text: string): { frontmatter: Record<string, string>; body: string } {
57	  const lines = text.split(/\r?\n/)
58	  if (lines[0]?.trim() !== '---') return { frontmatter: {}, body: text }
59	  const end = lines.findIndex((line, i) => i > 0 && line.trim() === '---')
60	  if (end === -1) return { frontmatter: {}, body: text }
61	  const frontmatter: Record<string, string> = {}
62	  for (let i = 1; i < end; i++) {
63	    const match = /^([A-Za-z0-9_-]+):\s*(.*)$/.exec(lines[i]!)
64	    if (!match) continue
65	    const key = match[1]!
66	    const value = match[2]!.trim()
67	    if (/^[>|]-?$/.test(value)) {
68	      const block: string[] = []
69	      while (i + 1 < end && /^\s+\S/.test(lines[i + 1]!)) block.push(lines[++i]!.trim())
70	      frontmatter[key] = block.join(value.startsWith('>') ? ' ' : '\n')
71	    } else {
72	      frontmatter[key] = unquote(value)
73	    }
74	  }
75	  return { frontmatter, body: lines.slice(end + 1).join('\n').replace(/^\n+/, '') }
76	}
77	
78	function unquote(value: string): string {
79	  const quoted = /^(["'])(.*)\1$/.exec(value)
80	  return quoted ? quoted[2]! : value
81	}
82	
83	async function readOptional(path: string): Promise<string | undefined> {
84	  try {
85	    return await readFile(path, 'utf8')
86	  } catch (error) {
87	    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return undefined
88	    throw error
89	  }
90	}
